start = time.time()
result = find_girth_ge7_graph(24, 3)
print(f"Search took {time.time() - start:.2f} seconds")
print("Number of edges:", len(result) if result else 0)
print("All edges:", result)

# Verify the result
if result:
    n = 24
    adj = [set() for _ in range(n)]
    for u, v in result:
        adj[u].add(v)
        adj[v].add(u)

    print("Degrees:", [len(adj[i]) for i in range(n)])

    # Check girth
    def find_girth(adj, n):
        min_cycle = float('inf')
        for start in range(n):
            from collections import deque
            dist = {start: 0}
            parent = {start: -1}
            queue = deque([start])
            while queue:
                u = queue.popleft()
                for v in adj[u]:
                    if v not in dist:
                        dist[v] = dist[u] + 1
                        parent[v] = u
                        queue.append(v)
                    elif parent[u] != v and parent[v] != u:
                        # Found a cycle
                        cycle_len = dist[u] + dist[v] + 1
                        min_cycle = min(min_cycle, cycle_len)
            if min_cycle <= 6:
                return min_cycle
        return min_cycle

    g = find_girth(adj, n)
    print("Girth:", g)
